import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

// Human Geography lessons with videos
const HUMAN_GEOGRAPHY_LESSONS = [
  { lesson_number: 1, title: "Geography Fundamentals", videos: [{ id: 1, title: "What is Geography?", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Maps & Navigation", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Scale & Regions", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Human-Environment Interaction", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Place & Space", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 2, title: "Population & Migration", videos: [{ id: 1, title: "Population Distribution", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Population Growth", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Migration Patterns", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Refugees & Displaced Persons", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Demographic Transition", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 3, title: "Culture & Society", videos: [{ id: 1, title: "Culture Diffusion", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Language & Identity", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Religion & Belief Systems", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Cultural Regions", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Globalization & Culture", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 4, title: "Political Geography", videos: [{ id: 1, title: "States & Sovereignty", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Boundaries & Borders", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Geopolitics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Territorial Disputes", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "International Relations", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 5, title: "Economic Geography", videos: [{ id: 1, title: "Economic Systems", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Resource Distribution", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Global Trade", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Development Disparities", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Economic Sectors", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 6, title: "Urbanization", videos: [{ id: 1, title: "Urbanization Process", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "City Structure", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Megacities", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Urban Issues", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Sustainable Cities", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 7, title: "Agricultural Geography", videos: [{ id: 1, title: "Agricultural Systems", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Land Use", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Food Security", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Green Revolution", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Sustainable Agriculture", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 8, title: "Environmental Geography", videos: [{ id: 1, title: "Natural Hazards", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Climate & Weather", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Ecosystems", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Resource Management", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Environmental Change", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 9, title: "Development & Globalization", videos: [{ id: 1, title: "Development Levels", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Global Economy", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Supply Chains", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Cultural Homogenization", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Future Geographies", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 10, title: "Regional Geography", videos: [{ id: 1, title: "Europe", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Asia", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Africa", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Americas", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Oceania & Polar Regions", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] }
];

export default function HumanGeography() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    setSub("Human Geography");
    setLessons(HUMAN_GEOGRAPHY_LESSONS);
    setLoading(false);
  }, []);

  if (loading) return <div>Loading...</div>;

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>{sub}</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
